#!/usr/bin/env python3
"""Compute v3.1 ground truth for CSX-308_Q1."""

from __future__ import annotations

import csv
import json
import re
from collections import Counter
from pathlib import Path
from typing import Any


TASK_ID = "CSX-308_Q1"
EVENT_ID = "CSX-308"


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_root() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / "CSX-308"


def read_json(root: Path, rel_path: str) -> Any:
    return json.loads((root / rel_path).read_text(encoding="utf-8"))


def extract_report_impacts(text: str) -> dict[str, int]:
    deaths = re.search(r"([0-9,]+)\s+people died", text, flags=re.IGNORECASE)
    homes = re.search(r"([0-9,]+)\s+homes were destroyed", text, flags=re.IGNORECASE)
    if not deaths or not homes:
        raise ValueError("Could not extract impact counts from event report text")
    return {
        "reported_deaths": int(deaths.group(1).replace(",", "")),
        "reported_destroyed_homes": int(homes.group(1).replace(",", "")),
    }


def find_volcano_catalog_feature(root: Path) -> dict[str, Any]:
    catalog = read_json(
        root,
        "data/event_catalogs/event_catalogs_005_04_event_specific_disaster_catalog_GDACS_event_list_for_package_time_window.json.json",
    )
    for feature in catalog.get("features", []):
        props = feature.get("properties", {})
        if props.get("eventtype") == "VO" and "nyiragongo" in props.get("eventname", "").lower():
            return feature
    raise ValueError("Could not locate Nyiragongo volcano catalog feature")


def manifest_summary(root: Path) -> dict[str, Any]:
    with (root / "metadata/files.csv").open(newline="", encoding="utf-8-sig") as handle:
        rows = list(csv.DictReader(handle))
    return {
        "total_files": len(rows),
        "category_counts": dict(Counter(row["data_category"] for row in rows)),
        "successful_or_remote_verified_files": sum(
            row["file_status"] in {"success", "remote_verified"} for row in rows
        ),
    }


def r4(value: float) -> float:
    return round(float(value), 4)


def main() -> None:
    root = package_root()
    event = read_json(root, "metadata/event.json")
    anchor = read_json(
        root,
        "data/event_reports/event_reports_003_Locked_event_anchor_2021_Mount_Nyiragongo_eruption.json",
    )
    report = read_json(root, "data/event_reports/event_reports_002_Wikipedia_2021_Mount_Nyiragongo_eruption.json")
    impacts = extract_report_impacts(report["extract"])
    catalog_feature = find_volcano_catalog_feature(root)
    catalog_props = catalog_feature["properties"]
    population = read_json(root, "data/exposure_impact/exposure_impact_002_WorldPop_GP_100m_population_sum.json")
    surface_change = read_json(root, "data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json")
    embedding_change = read_json(root, "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json")
    rainfall = read_json(root, "data/physical_hazard/physical_hazard_005_GPM_IMERG_V07_event_accumulated_precipitation.json")

    population_rounded = round(population["population_sum"]["population"])
    surface_change_mean = r4(surface_change["stats"]["sentinel2_dnbr_mean"])
    embedding_change_mean = r4(embedding_change["stats"]["alphaearth_1_minus_cosine_mean"])

    primary_gt = {
        "answer": "urban_lava_flow_impact",
        "response_priority": "life_safety_evacuation_and_emergency_shelter",
        "key_numeric_anchors": {
            "catalog_alert_level": catalog_props["alertlevel"],
            "reported_deaths": impacts["reported_deaths"],
            "reported_destroyed_homes": impacts["reported_destroyed_homes"],
            "aoi_population_rounded": population_rounded,
            "mean_surface_change_index": surface_change_mean,
        },
        "impact_chain": [
            "volcanic eruption and lava displacement near Goma",
            "fatalities, housing loss, and urban population exposure",
            "life safety evacuation, shelter, and displacement support",
        ],
        "why_alternatives_are_weaker": [
            "ash-centered disruption is not the dominant documented impact pathway",
            "rainfall or lahar flooding is contextual rather than primary",
            "surface change alone misses the reported urban humanitarian impact",
        ],
    }

    judge_anchors = {
        "canonical_stance": (
            "Immediate operations should be driven by a lava-flow urban impact and displacement chain "
            "near Goma, not by ash, rainfall/lahar flooding, or image-change context alone."
        ),
