        ],
        "required_metrics": [
            {"name": "catalog_alert_level", "expected": catalog_props["alertlevel"]},
            {"name": "reported_deaths", "expected": impacts["reported_deaths"], "tolerance": 0},
            {"name": "reported_destroyed_homes", "expected": impacts["reported_destroyed_homes"], "tolerance": 0},
            {"name": "aoi_population_rounded", "expected": population_rounded, "tolerance": 2},
            {"name": "mean_surface_change_index", "expected": surface_change_mean, "tolerance": 0.0005},
        ],
        "forbidden_claims": [
            "Claims a precise lava-flow footprint from this task alone.",
            "Treats the population summary as a direct affected-population count.",
            "Identifies ash/aviation disruption or rainfall/lahar flooding as the primary mechanism.",
            "Infers exact displacement, road closure, hospital outage, or infrastructure loss counts beyond the anchors.",
        ],
        "acceptable_variants": [
            "urban_lava_displacement",
            "lava_driven_urban_impact",
