            "reported_destroyed_homes": {"expected": impacts["reported_destroyed_homes"], "tolerance": 0},
            "aoi_population_rounded": {"expected": population_rounded, "tolerance": 2},
            "mean_surface_change_index": {"expected": surface_change_mean, "tolerance": 0.0005},
            "mean_embedding_change_context": {"expected": embedding_change_mean, "tolerance": 0.0005},
        },
        "reasoning_requirements": [
            "Connect the volcano trigger to urban exposure and displacement-oriented operations.",
            "Use numeric anchors to support the chain without treating them as a complete damage model.",
            "Separate contextual remote-sensing and rainfall signals from the dominant impact pathway.",
        ],
        "forbidden_overclaims": [
            "Do not claim a precise lava-flow footprint from this task alone.",
            "Do not turn the AOI population summary into a direct affected-population count.",
            "Do not claim ash/aviation disruption or rainfall/lahar flooding as the primary disaster mechanism.",
            "Do not infer exact displacement, road closure, hospital outage, or infrastructure loss counts beyond the package anchors.",
        ],
        "key_values": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "scale": event["scale"],
            "region": event["region"],
            "event_dates": {
                "start": anchor["temporal_window"]["start_date"],
                "end": anchor["temporal_window"]["end_date"],
            },
            "catalog": {
                "eventtype": catalog_props["eventtype"],
                "eventname": catalog_props["eventname"].strip(),
                "alert_level": catalog_props["alertlevel"],
                "country": catalog_props["country"],
                "coordinates": catalog_feature["geometry"]["coordinates"],
            },
            "context_metrics": {
                "raw_population_sum": population["population_sum"]["population"],
                "surface_change_max": r4(surface_change["stats"]["sentinel2_dnbr_max"]),
                "embedding_change_mean": embedding_change_mean,
                "event_precipitation_mean_mm": round(float(rainfall["stats"]["gpm_event_precip_mm_mean"]), 2),
            },
            "manifest": manifest_summary(root),
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
